public class H2ShutdownConfig {

    private final JdbcTemplate jdbc;

    public H2ShutdownConfig(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @PreDestroy
    void shutdownH2() {
        try {
            jdbc.execute("SHUTDOWN");
        } catch (Exception ignored) {
            // 库已随连接关闭时无需处理
        }
    }
}

