3	import com.example.starter.AbstractIntegrationTest;
4	import com.example.starter.catalog.DocumentCatalog;
5	import com.example.starter.domain.PublicityStatus;
6	import com.example.starter.domain.ReviewStatus;
7	import com.example.starter.dto.DeclareRequest;
8	import com.example.starter.dto.LateDocumentRequest;
9	import com.example.starter.dto.ReviewView;
10	import com.example.starter.dto.ServiceResult;
11	import com.example.starter.time.RaceBusinessClock;
12	import org.junit.jupiter.api.Test;
13	import org.springframework.beans.factory.annotation.Autowired;
14	import org.springframework.boot.test.context.TestConfiguration;
15	import org.springframework.context.annotation.Bean;
16	import org.springframework.context.annotation.Import;
17	import org.springframework.context.annotation.Primary;
18	
19	import java.time.Instant;
20	import java.time.LocalDate;
21	import java.time.ZoneOffset;
22	import java.util.ArrayList;
23	import java.util.List;
24	import java.util.concurrent.CountDownLatch;
25	import java.util.concurrent.CyclicBarrier;
26	import java.util.concurrent.ExecutorService;
27	import java.util.concurrent.Executors;
28	import java.util.concurrent.Future;
29	import java.util.concurrent.TimeUnit;
30	
31	import static org.junit.jupiter.api.Assertions.assertEquals;
32	import static org.junit.jupiter.api.Assertions.assertTrue;
33	
34	/**
35	 * H2 真实并发测试：
36	 * 1) 同一批号同时刻并发申报仅唯一受理；
37	 * 2) 公示期满生效与异议受理并发，行锁保证唯一终态，不得既签发又受理异议。
38	 */
39	@Import(ReviewConcurrencyTest.RaceClockConfig.class)
40	class ReviewConcurrencyTest extends AbstractIntegrationTest {
41	
42	    /** 本测试类专用：竞态时钟作为主 BusinessClock，支持按线程标签返回时刻。 */
43	    @TestConfiguration
44	    static class RaceClockConfig {
45	        @Bean
46	        @Primary
47	        RaceBusinessClock raceBusinessClock() {
48	            return new RaceBusinessClock();
49	        }
50	    }
51	
52	    @Autowired
53	    private RaceBusinessClock raceClock;
54	
55	    @Test
56	    void concurrentDeclarationsOfSameBatchAcceptExactlyOne() throws Exception {
57	        raceClock.setFallback(Instant.parse("2026-09-01T00:00:00Z"));
58	        int threads = 8;
59	        ExecutorService pool = Executors.newFixedThreadPool(threads);
60	        CyclicBarrier barrier = new CyclicBarrier(threads);
61	        CountDownLatch done = new CountDownLatch(threads);
62	        List<Future<ServiceResult>> futures = new ArrayList<>();
63	
64	        for (int i = 0; i < threads; i++) {
65	            final int index = i;
66	            futures.add(pool.submit(() -> {
67	                DeclareRequest request = declareRequest("race-declare-" + index, "B-RACE-DECLARE",
68	                        allDocuments(), boundaryPassingInspections());
69	                barrier.await(5, TimeUnit.SECONDS);
70	                try {
71	                    return reviewService.declare(request);
72	                } finally {
73	                    done.countDown();
74	                }
75	            }));
76	        }
77	        assertTrue(done.await(30, TimeUnit.SECONDS), "并发申报必须在超时前全部返回");
78	        pool.shutdown();
79	
80	        List<Integer> statuses = new ArrayList<>();
81	        for (Future<ServiceResult> future : futures) {
82	            statuses.add(future.get(10, TimeUnit.SECONDS).httpStatus());
83	        }
84	        long accepted = statuses.stream().filter(s -> s == 200).count();
85	        long rejected = statuses.stream().filter(s -> s == 409).count();
86	        assertEquals(1, accepted, "同一批号并发申报只允许唯一受理");
87	        assertEquals(threads - 1, rejected, "其余并发申报必须 409 落败");
88	        assertEquals(1, countByBatch("B-RACE-DECLARE"));
89	    }
90	
91	    @Test
92	    void publicitySettlementAndObjectionRaceProducesSingleTerminalState() throws Exception {
93	        // 多轮竞态：异议线程时间为期满前 1 秒（仍在公示期内），生效线程时间恰为期满日界。
94	        // 谁先拿到行锁谁成为唯一终态；另一个操作必须失败，绝不能两个都成功。
95	        for (int round = 0; round < 10; round++) {
96	            String batchNo = "B-RACE-PUB-" + round;
97	            raceClock.setFallback(Instant.parse("2026-09-07T00:00:00Z"));
98	            reviewService.declare(declareRequest("race-pub-d-" + round, batchNo,
99	                    allDocuments(), boundaryPassingInspections()));
100	            reviewService.evaluate(batchNo);
101	
102	            ReviewView before = reviewService.getReview(batchNo);
103	            LocalDate endUtc = before.publicityEndUtc();
104	            Instant boundary = endUtc.atStartOfDay(ZoneOffset.UTC).toInstant();
105	            raceClock.setTime("objection", boundary.minusSeconds(1));
106	            raceClock.setTime("settle", boundary);
107	
108	            ExecutorService pool = Executors.newFixedThreadPool(2);
109	            CyclicBarrier barrier = new CyclicBarrier(2);
110	            Future<Outcome> objectionFuture = pool.submit(() ->
111	                    runTagged("objection", barrier, () -> {
112	                        try {
113	                            reviewService.acceptObjection(batchNo);
114	                            return Outcome.SUCCESS;
115	                        } catch (BusinessException ex) {
116	                            return Outcome.FAILED;
117	                        }
118	                    }));
119	            Future<Outcome> settleFuture = pool.submit(() ->
120	                    runTagged("settle", barrier, () -> {
121	                        try {
122	                            reviewService.settlePublicity(batchNo);
123	                            return Outcome.SUCCESS;
124	                        } catch (BusinessException ex) {
125	                            return Outcome.FAILED;
126	                        }
127	                    }));
128	
129	            Outcome objectionResult = objectionFuture.get(30, TimeUnit.SECONDS);
130	            Outcome settleResult = settleFuture.get(30, TimeUnit.SECONDS);
131	            pool.shutdown();
132	
133	            // 关键断言：两个操作不能同时成功
134	            assertTrue(!(objectionResult == Outcome.SUCCESS && settleResult == Outcome.SUCCESS),
135	                    "第 " + round + " 轮：异议受理与期满生效不得同时成功");
136	            assertTrue(objectionResult == Outcome.SUCCESS || settleResult == Outcome.SUCCESS,
137	                    "第 " + round + " 轮：必须恰好有一个操作成功形成终态");
138	
139	            ReviewView after = reviewService.getReview(batchNo);
140	            String publicityStatus = after.publicity().status();
141	            if (objectionResult == Outcome.SUCCESS) {
142	                assertEquals(ReviewStatus.OBJECTION_REVIEW.name(), after.status(),
143	                        "第 " + round + " 轮：异议胜出则唯一终态为异议复核");
144	                assertEquals(PublicityStatus.OBJECTION_REVIEW.name(), publicityStatus);
145	                assertEquals(Outcome.FAILED, settleResult);
146	            } else {
147	                assertEquals(ReviewStatus.PUBLICITY_EFFECTIVE.name(), after.status(),
148	                        "第 " + round + " 轮：生效胜出则唯一终态为期满生效");
149	                assertEquals(PublicityStatus.EFFECTIVE.name(), publicityStatus);
150	                assertEquals(Outcome.FAILED, objectionResult);
151	            }
152	            assertEquals(1, countPublicity(batchNo), "公示记录只能有一行，不得重复生效");
153	        }
154	    }
155	
156	    @Test
157	    void archivedBatchRecordsLateDocumentsWithoutChangingTerminalState() {
158	        raceClock.setFallback(Instant.parse("2026-09-07T00:00:00Z"));
159	        reviewService.declare(declareRequest("arch-d", "B-ARCH-1",
160	                allDocuments(), boundaryPassingInspections()));
161	        reviewService.evaluate("B-ARCH-1");
162	        raceClock.setFallback(Instant.parse("2026-09-14T00:00:00Z"));
163	        reviewService.settlePublicity("B-ARCH-1");
164	        reviewService.issue("B-ARCH-1", new com.example.starter.dto.IssueRequest("arch-i"));
165	
166	        Integer eventsBefore = countLateEvents("B-ARCH-1");
167	        ServiceResult late = reviewService.reportLateDocument("B-ARCH-1",
168	                new LateDocumentRequest(List.of(DocumentCatalog.STABILITY_REPORT, DocumentCatalog.BATCH_RECORD)));
169	        assertEquals(200, late.httpStatus());
170	
171	        ReviewView view = reviewService.getReview("B-ARCH-1");
172	        assertEquals(ReviewStatus.ISSUED.name(), view.status(), "迟到资料不得改变签发归档终态");
173	        assertEquals(eventsBefore + 1, countLateEvents("B-ARCH-1"), "迟到资料只登记一条迟到事件");
174	
175	        var events = reviewService.listEvents("B-ARCH-1");
176	        assertTrue(events.stream().anyMatch(e -> e.get("eventType").equals("LATE_DOCUMENT")));
177	    }
178	
179	    private Outcome runTagged(String tag, CyclicBarrier barrier, java.util.concurrent.Callable<Outcome> action) {
180	        raceClock.tagCurrentThread(tag);
181	        try {
182	            barrier.await(5, TimeUnit.SECONDS);
183	            return action.call();
184	        } catch (Exception ex) {
185	            throw new RuntimeException(ex);
186	        } finally {
187	            raceClock.tagCurrentThread(null);
188	        }
189	    }
190	
191	    private int countByBatch(String batchNo) {
192	        Integer count = jdbc.queryForObject(
193	                "SELECT COUNT(*) FROM batch_review WHERE batch_no = ?", Integer.class, batchNo);
194	        return count == null ? 0 : count;
195	    }
196	
197	    private int countPublicity(String batchNo) {
198	        Integer count = jdbc.queryForObject("""
199	                SELECT COUNT(*) FROM publicity_record p
200	                JOIN batch_review r ON r.id = p.review_id
201	                WHERE r.batch_no = ?
202	                """, Integer.class, batchNo);
203	        return count == null ? 0 : count;
204	    }
205	
206	    private Integer countLateEvents(String batchNo) {
207	        return jdbc.queryForObject("""
208	                SELECT COUNT(*) FROM review_event e
209	                JOIN batch_review r ON r.id = e.review_id
210	                WHERE r.batch_no = ? AND e.event_type = 'LATE_DOCUMENT'
211	                """, Integer.class, batchNo);
212	    }
213	
214	    private enum Outcome {
215	        SUCCESS, FAILED, NEITHER
216	    }
217	}
