    assertNotEquals(Fingerprints.customsRevise("CIQ-1", new CustomsReviseRequest("req-c3", 1, 200)),
            Fingerprints.customsRevise("CIQ-1", new CustomsReviseRequest("req-c3", 1, 300)));
